    def get_running_python_processes(self):
        python_processes = []
        for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
            try:
                if 'python' in proc.info['name'].lower():
                    cmd_line = proc.info['cmdline']
                    if cmd_line:
                        module_name = Path(cmd_line[-1]).name  # Get actual filename
                        python_processes.append({
                            'pid': proc.info['pid'],
                            'name': module_name,  # Use actual filename
                            'cpu': proc.cpu_percent(),
                            'memory': proc.memory_info().rss / 1024 / 1024,
                            'status': 'running'
                        })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        # Add available modules
        for module in self.available_modules:
            if not any(p['name'] == module['name'] for p in python_processes):
                python_processes.append(module)

        return python_processes
