def _ask_mistral_sync(prompt: str, max_new_tokens: int = 64, temperature: float = 0.7) -> str:
    """Synchronous Mistral inference - runs in thread pool"""
    logger.info(f"🧠 AI Processing: {prompt[:50]}...")
    start_time = time.time()
    try:
        inputs = tokenizer(prompt, return_tensors="pt")
        inputs = {k: v.to(model.device) for k, v in inputs.items()}

        with torch.no_grad():
            output_ids = model.generate(
                **inputs,
                max_new_tokens=max_new_tokens,
                temperature=temperature,
                do_sample=True,
                pad_token_id=tokenizer.eos_token_id,
            )

        generated_text = tokenizer.decode(output_ids[0], skip_special_tokens=True)
        if generated_text.startswith(prompt):
            generated_text = generated_text[len(prompt):].lstrip()
        elapsed = time.time() - start_time
        logger.info(f"✅ AI Response generated in {elapsed:.1f}s: {generated_text[:50]}...")
        return generated_text
    except Exception as e:
        logger.error(f"❌ AI Error: {e}")
        raise

async def ask_mistral(prompt: str, max_new_tokens: int = 64, temperature: float = 0.7) -> str:
    """Async wrapper for Mistral inference with timeout"""
    loop = asyncio.get_running_loop()
    func = partial(_ask_mistral_sync, prompt, max_new_tokens, temperature)
    try:
        return await asyncio.wait_for(
            loop.run_in_executor(ai_executor, func),
            timeout=AI_TIMEOUT_SECONDS
        )
    except asyncio.TimeoutError:
        logger.error(f"❌ AI Timeout after {AI_TIMEOUT_SECONDS}s")
        return "I'm sorry, the response took too long. Please try a shorter question."

